const CATEGORY_MAP = {
  expense: ["餐饮", "交通", "购物", "居住", "娱乐", "医疗", "教育", "其他支出"],
  income: ["工资", "奖金", "兼职", "投资", "红包", "其他收入"]
};

const TYPE_LABEL = { income: "收入", expense: "支出" };

const state = await appStore.getState();
if (!state || typeof state !== "object") {
  throw new Error("无法读取应用数据");
}

// 仅当业务键不存在时初始化种子（空数组表示用户已清空）
if (!Array.isArray(state.records)) {
  state.records = [];
}
if (typeof state.filterMonth !== "string") {
  state.filterMonth = "";
}

const els = {
  monthInput: document.querySelector("#monthInput"),
  monthAllBtn: document.querySelector("#monthAllBtn"),
  statIncome: document.querySelector("#statIncome"),
  statExpense: document.querySelector("#statExpense"),
  statBalance: document.querySelector("#statBalance"),
  statIncomeCount: document.querySelector("#statIncomeCount"),
  statExpenseCount: document.querySelector("#statExpenseCount"),
  statTotalCount: document.querySelector("#statTotalCount"),
  form: document.querySelector("#recordForm"),
  dateInput: document.querySelector("#dateInput"),
  categoryInput: document.querySelector("#categoryInput"),
  amountInput: document.querySelector("#amountInput"),
  noteInput: document.querySelector("#noteInput"),
  formError: document.querySelector("#formError"),
  resetBtn: document.querySelector("#resetBtn"),
  recordList: document.querySelector("#recordList"),
  emptyState: document.querySelector("#emptyState"),
  listScope: document.querySelector("#listScope"),
  dialogBackdrop: document.querySelector("#dialogBackdrop"),
  dialogText: document.querySelector("#dialogText"),
  dialogCancel: document.querySelector("#dialogCancel"),
  dialogConfirm: document.querySelector("#dialogConfirm")
};

function pad2(n) {
  return String(n).padStart(2, "0");
}

function todayISO() {
  const d = new Date();
  return d.getFullYear() + "-" + pad2(d.getMonth() + 1) + "-" + pad2(d.getDate());
}

function currentMonth() {
  return todayISO().slice(0, 7);
}

function formatMoney(value) {
  const num = Number(value) || 0;
  const sign = num < 0 ? "-" : "";
  return sign + "¥" + Math.abs(num).toFixed(2);
}

function getType() {
  const checked = document.querySelector('input[name="type"]:checked');
  return checked && checked.value === "income" ? "income" : "expense";
}

function setType(type) {
  const target = document.querySelector('input[name="type"][value="' + type + '"]');
  if (target) target.checked = true;
}

function fillCategories(type, keepValue) {
  const list = CATEGORY_MAP[type] || CATEGORY_MAP.expense;
  els.categoryInput.textContent = "";
  list.forEach(function (name) {
    const opt = document.createElement("option");
    opt.value = name;
    opt.textContent = name;
    els.categoryInput.appendChild(opt);
  });
  if (keepValue && list.indexOf(keepValue) !== -1) {
    els.categoryInput.value = keepValue;
  }
}

function showError(message) {
  if (!message) {
    els.formError.hidden = true;
    els.formError.textContent = "";
    return;
  }
  els.formError.textContent = message;
  els.formError.hidden = false;
}

function normalizeRecord(raw) {
  const rec = raw && typeof raw === "object" ? raw : {};
  return {
    id: typeof rec.id === "string" && rec.id ? rec.id : "rec_" + Math.random().toString(36).slice(2, 10) + Date.now().toString(36),
    date: typeof rec.date === "string" ? rec.date : "",
    type: rec.type === "income" ? "income" : "expense",
    category: typeof rec.category === "string" ? rec.category : "其他支出",
    amount: Number(rec.amount) || 0,
    note: typeof rec.note === "string" ? rec.note : ""
  };
}

function getRecords() {
  return (Array.isArray(state.records) ? state.records : []).map(normalizeRecord);
}

function getFilteredRecords() {
  const month = state.filterMonth;
  const all = getRecords();
  if (!month) return all;
  return all.filter(function (r) {
    return typeof r.date === "string" && r.date.slice(0, 7) === month;
  });
}

function computeStats(records) {
  let income = 0;
  let expense = 0;
  let incomeCount = 0;
  let expenseCount = 0;
  records.forEach(function (r) {
    if (r.type === "income") {
      income += r.amount;
      incomeCount += 1;
    } else {
      expense += r.amount;
      expenseCount += 1;
    }
  });
  return {
    income: income,
    expense: expense,
    balance: income - expense,
    incomeCount: incomeCount,
    expenseCount: expenseCount,
    total: records.length
  };
}

function renderStats(records) {
  const s = computeStats(records);
  els.statIncome.textContent = formatMoney(s.income);
  els.statExpense.textContent = formatMoney(s.expense);
  els.statBalance.textContent = formatMoney(s.balance);
  els.statBalance.classList.toggle("is-negative", s.balance < 0);
  els.statIncomeCount.textContent = s.incomeCount + " 笔";
  els.statExpenseCount.textContent = s.expenseCount + " 笔";
  els.statTotalCount.textContent = "共 " + s.total + " 笔记录";
}

function renderList(records) {
  els.recordList.textContent = "";
  const sorted = records.slice().sort(function (a, b) {
    if (a.date === b.date) return 0;
    return a.date < b.date ? 1 : -1;
  });

  sorted.forEach(function (rec) {
    const li = document.createElement("li");
    li.className = "record-item " + (rec.type === "income" ? "is-income" : "is-expense");
    li.dataset.recordId = rec.id;

    const main = document.createElement("div");
    main.className = "record-main";

    const top = document.createElement("div");
    top.className = "record-top";

    const cat = document.createElement("span");
    cat.className = "record-category";
    cat.textContent = rec.category;

    const tag = document.createElement("span");
    tag.className = "tag " + (rec.type === "income" ? "tag-income" : "tag-expense");
    tag.textContent = TYPE_LABEL[rec.type];

    const date = document.createElement("span");
    date.className = "record-date";
    date.textContent = rec.date || "未填日期";

    top.appendChild(cat);
    top.appendChild(tag);
    top.appendChild(date);
    main.appendChild(top);

    if (rec.note) {
      const note = document.createElement("p");
      note.className = "record-note";
      note.textContent = rec.note;
      main.appendChild(note);
    }

    const side = document.createElement("div");
    side.className = "record-side";

    const amount = document.createElement("span");
    amount.className = "record-amount " + (rec.type === "income" ? "is-income" : "is-expense");
    amount.textContent = (rec.type === "income" ? "+" : "-") + formatMoney(rec.amount);

    const delBtn = document.createElement("button");
    delBtn.type = "button";
    delBtn.className = "btn btn-ghost btn-mini";
    delBtn.dataset.action = "delete";
    delBtn.dataset.recordId = rec.id;
    delBtn.textContent = "删除";

    side.appendChild(amount);
    side.appendChild(delBtn);

    li.appendChild(main);
    li.appendChild(side);
    els.recordList.appendChild(li);
  });

  els.emptyState.hidden = sorted.length > 0;
  els.listScope.textContent = state.filterMonth ? state.filterMonth + " 月" : "全部月份";
}

function render() {
  const filtered = getFilteredRecords();
  renderStats(filtered);
  renderList(filtered);
  els.monthInput.value = state.filterMonth || "";
}

function openDialog(message) {
  els.dialogText.textContent = message;
  els.dialogBackdrop.hidden = false;
  els.dialogConfirm.focus();
}

function closeDialog() {
  els.dialogBackdrop.hidden = true;
  els.dialogText.textContent = "";
}

function askConfirm(message) {
  return new Promise(function (resolve) {
    let settled = false;
    function cleanup() {
      els.dialogConfirm.removeEventListener("click", onConfirm);
      els.dialogCancel.removeEventListener("click", onCancel);
      els.dialogBackdrop.removeEventListener("click", onBackdrop);
      document.removeEventListener("keydown", onKey);
    }
    function finish(value) {
      if (settled) return;
      settled = true;
      cleanup();
      closeDialog();
      resolve(value);
    }
    function onConfirm() { finish(true); }
    function onCancel() { finish(false); }
    function onBackdrop(e) { if (e.target === els.dialogBackdrop) finish(false); }
    function onKey(e) { if (e.key === "Escape") finish(false); }

    els.dialogConfirm.addEventListener("click", onConfirm);
    els.dialogCancel.addEventListener("click", onCancel);
    els.dialogBackdrop.addEventListener("click", onBackdrop);
    document.addEventListener("keydown", onKey);
    openDialog(message);
  });
}

async function persist(nextRecords, nextFilterMonth) {
  const next = Object.assign({}, state, {
    records: nextRecords,
    filterMonth: typeof nextFilterMonth === "string" ? nextFilterMonth : state.filterMonth
  });
  await appStore.setState(next);
  const fresh = await appStore.getState();
  if (!fresh || typeof fresh !== "object") {
    throw new Error("保存后无法读取数据");
  }
  state.records = Array.isArray(fresh.records) ? fresh.records : [];
  state.filterMonth = typeof fresh.filterMonth === "string" ? fresh.filterMonth : "";
  Object.keys(fresh).forEach(function (key) {
    if (!(key in state)) state[key] = fresh[key];
  });
}

async function handleSubmit(e) {
  e.preventDefault();
  showError("");

  const date = els.dateInput.value;
  const type = getType();
  const category = els.categoryInput.value;
  const amountRaw = els.amountInput.value.trim();
  const note = els.noteInput.value.trim();

  if (!date) {
    showError("请选择日期。");
    return;
  }
  if (!/^\d{4}-\d{2}-\d{2}$/.test(date)) {
    showError("日期格式不正确，请重新选择。");
    return;
  }
  if (!category) {
    showError("请选择分类。");
    return;
  }
  if (amountRaw === "") {
    showError("请输入金额。");
    return;
  }
  const amount = Number(amountRaw);
  if (!isFinite(amount) || amount <= 0) {
    showError("金额需为大于 0 的数字。");
    return;
  }
  const rounded = Math.round(amount * 100) / 100;

  const record = {
    id: "rec_" + Math.random().toString(36).slice(2, 10) + Date.now().toString(36),
    date: date,
    type: type,
    category: category,
    amount: rounded,
    note: note
  };

  const nextRecords = getRecords().concat([record]);
  try {
    await persist(nextRecords);
  } catch (err) {
    showError("保存失败：" + (err && err.message ? err.message : "未知错误") + "，请重试。");
    return;
  }

  els.amountInput.value = "";
  els.noteInput.value = "";
  render();
}

async function handleDelete(recordId) {
  const target = getRecords().filter(function (r) { return r.id === recordId; })[0];
  if (!target) {
    render();
    return;
  }
  const label = TYPE_LABEL[target.type] + " · " + target.category + " · " + formatMoney(target.amount) +
    (target.date ? "（" + target.date + "）" : "");
  const ok = await askConfirm("确定删除这条记录吗？" + label + " 删除后无法恢复。");
  if (!ok) return;

  const nextRecords = getRecords().filter(function (r) { return r.id !== recordId; });
  try {
    await persist(nextRecords);
  } catch (err) {
    showError("删除失败：" + (err && err.message ? err.message : "未知错误") + "，请重试。");
    return;
  }
  render();
}

async function handleMonthChange(value) {
  try {
    await persist(getRecords(), value);
  } catch (err) {
    showError("筛选保存失败：" + (err && err.message ? err.message : "未知错误"));
    return;
  }
  render();
}

function resetForm() {
  els.dateInput.value = todayISO();
  setType("expense");
  fillCategories("expense");
  els.amountInput.value = "";
  els.noteInput.value = "";
  showError("");
}

async function init() {
  els.dateInput.value = todayISO();
  fillCategories("expense");
  render();

  els.form.addEventListener("submit", handleSubmit);

  document.querySelectorAll('input[name="type"]').forEach(function (radio) {
    radio.addEventListener("change", function () {
      fillCategories(getType());
    });
  });

  els.resetBtn.addEventListener("click", resetForm);

  els.monthInput.addEventListener("change", function () {
    handleMonthChange(els.monthInput.value || "");
  });

  els.monthAllBtn.addEventListener("click", function () {
    handleMonthChange("");
  });

  els.recordList.addEventListener("click", function (e) {
    const btn = e.target.closest('button[data-action="delete"]');
    if (!btn) return;
    const id = btn.dataset.recordId;
    if (!id) return;
    handleDelete(id);
  });
}

await init();

artifact.css:
:root {
  --bg-deep: #0f1b2d;
  --bg-mid: #16263d;
  --panel: #1d3049;
  --panel-soft: #24395a;
  --line: #33507a;
  --text: #eaf1fb;
  --text-dim: #9db2d0;
  --accent: #4ea8ff;
  --accent-strong: #2b8bf0;
  --income: #35d39a;
  --expense: #ff7a86;
  --danger: #e5484d;
  --radius: 14px;
}

#app {
  min-height: 100vh;
  background: radial-gradient(1200px 600px at 12% -10%, #1e3a5f 0%, transparent 60%),
              linear-gradient(160deg, var(--bg-deep) 0%, var(--bg-mid) 55%, #101d30 100%);
  color: var(--text);
  font-family: "PingFang SC", "Microsoft YaHei", "Hiragino Sans GB", system-ui, -apple-system, sans-serif;
  font-size: 15px;
  line-height: 1.6;
  padding: 28px 20px 56px;
  box-sizing: border-box;
}

#app * {
  box-sizing: border-box;
}

.app-shell {
  max-width: 1080px;
  margin: 0 auto;
  display: flex;
  flex-direction: column;
  gap: 22px;
}

/* ---------- header ---------- */
.app-header {
  display: flex;
  flex-wrap: wrap;
  gap: 18px;
  align-items: flex-end;
  justify-content: space-between;
  background: linear-gradient(135deg, rgba(78, 168, 255, 0.16), rgba(53, 211, 154, 0.08));
  border: 1px solid var(--line);
  border-radius: var(--radius);
  padding: 20px 22px;
}

.brand {
  display: flex;
  align-items: center;
  gap: 14px;
}

.brand-mark {
  width: 46px;
  height: 46px;
  border-radius: 12px;
  display: grid;
  place-items: center;
  font-size: 22px;
  font-weight: 700;
  color: #06203a;
  background: linear-gradient(140deg, var(--income), var(--accent));
  box-shadow: 0 6px 18px rgba(78, 168, 255, 0.35);
}

.brand-text h1 {
  margin: 0;
  font-size: 22px;
  letter-spacing: 0.5px;
}

.brand-sub {
  margin: 2px 0 0;
  color: var(--text-dim);
  font-size: 13px;
}

.month-filter {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.month-row {
  display: flex;
  gap: 8px;
  align-items: center;
}

/* ---------- stats ---------- */
.stats {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  gap: 14px;
}

.stat-card {
  background: var(--panel);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  padding: 16px 18px;
  position: relative;
  overflow: hidden;
}

.stat-card::before {
  content: "";
  position: absolute;
  inset: 0 auto 0 0;
  width: 4px;
  background: var(--accent);
}

.stat-income::before { background: var(--income); }
.stat-expense::before { background: var(--expense); }
.stat-balance::before { background: var(--accent); }

.stat-label {
  margin: 0;
  font-size: 13px;
  color: var(--text-dim);
  letter-spacing: 0.5px;
}

.stat-value {
  margin: 6px 0 2px;
  font-size: 26px;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
}

.stat-income .stat-value { color: var(--income); }
.stat-expense .stat-value { color: var(--expense); }
.stat-balance .stat-value { color: var(--accent); }
.stat-balance .stat-value.is-negative { color: var(--expense); }

.stat-meta {
  margin: 0;
  font-size: 12px;
  color: var(--text-dim);
}

/* ---------- layout ---------- */
.main-grid {
  display: grid;
  grid-template-columns: minmax(280px, 360px) 1fr;
  gap: 18px;
  align-items: start;
}

@media (max-width: 820px) {
  .main-grid {
    grid-template-columns: 1fr;
  }
}

.panel {
  background: var(--panel);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  padding: 18px 20px 22px;
}

.panel-title {
  margin: 0 0 14px;
  font-size: 16px;
  letter-spacing: 0.5px;
}

.panel-head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 10px;
}

.list-scope {
  font-size: 12px;
  color: var(--text-dim);
  background: var(--panel-soft);
  border: 1px solid var(--line);
  border-radius: 999px;
  padding: 2px 10px;
}

/* ---------- form ---------- */
.record-form {
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.form-row {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.field-label {
  font-size: 13px;
  color: var(--text-dim);
  letter-spacing: 0.4px;
}

.input {
  width: 100%;
  background: var(--panel-soft);
  color: var(--text);
  border: 1px solid var(--line);
  border-radius: 10px;
  padding: 9px 12px;
  font-size: 14px;
  font-family: inherit;
  outline: none;
  transition: border-color 0.15s ease, box-shadow 0.15s ease;
}

.input::placeholder {
  color: #7d93b3;
}

.input:focus {
  border-color: var(--accent);
  box-shadow: 0 0 0 3px rgba(78, 168, 255, 0.22);
}

select.input {
  appearance: none;
  background-image: linear-gradient(45deg, transparent 50%, var(--text-dim) 50%),
                    linear-gradient(135deg, var(--text-dim) 50%, transparent 50%);
  background-position: calc(100% - 18px) 50%, calc(100% - 13px) 50%;
  background-size: 5px 5px, 5px 5px;
  background-repeat: no-repeat;
  padding-right: 34px;
}

select.input option {
  background: var(--panel-soft);
  color: var(--text);
}

input[type="date"].input,
input[type="month"].input {
  color-scheme: dark;
}

.type-switch {
  display: flex;
  gap: 10px;
}

.type-option {
  flex: 1;
  cursor: pointer;
}

.type-option input {
  position: absolute;
  opacity: 0;
  pointer-events: none;
}

.type-pill {
  display: block;
  text-align: center;
  padding: 8px 10px;
  border-radius: 10px;
  border: 1px solid var(--line);
  background: var(--panel-soft);
  color: var(--text-dim);
  font-size: 14px;
  transition: all 0.15s ease;
}

.type-option input:checked + .type-pill-expense {
  background: rgba(255, 122, 134, 0.18);
  border-color: var(--expense);
  color: var(--expense);
  font-weight: 600;
}

.type-option input:checked + .type-pill-income {
  background: rgba(53, 211, 154, 0.18);
  border-color: var(--income);
  color: var(--income);
  font-weight: 600;
}

.type-option input:focus-visible + .type-pill {
  box-shadow: 0 0 0 3px rgba(78, 168, 255, 0.25);
}

.form-error {
  margin: 0;
  font-size: 13px;
  color: var(--expense);
  background: rgba(255, 122, 134, 0.12);
  border: 1px solid rgba(255, 122, 134, 0.4);
  border-radius: 10px;
  padding: 8px 12px;
}

.form-actions {
  display: flex;
  gap: 10px;
  margin-top: 2px;
}

/* ---------- buttons ---------- */
.btn {
  border: 1px solid transparent;
  border-radius: 10px;
  padding: 9px 16px;
  font-size: 14px;
  font-family: inherit;
  cursor: pointer;
  transition: transform 0.1s ease, background 0.15s ease, border-color 0.15s ease;
}

.btn:active {
  transform: translateY(1px);
}

.btn-primary {
  background: linear-gradient(135deg, var(--accent), var(--accent-strong));
  color: #04182c;
  font-weight: 700;
  flex: 1;
}

.btn-primary:hover {
  background: linear-gradient(135deg, #63b6ff, #3a97f5);
}

.btn-ghost {
  background: var(--panel-soft);
  border-color: var(--line);
  color: var(--text);
}

.btn-ghost:hover {
  border-color: var(--accent);
  color: var(--accent);
}

.btn-danger {
  background: var(--danger);
  color: #fff;
  font-weight: 600;
}

.btn-danger:hover {
  background: #f0575c;
}

.btn-mini {
  padding: 5px 12px;
  font-size: 13px;
  border-radius: 8px;
}

/* ---------- list ---------- */
.record-list {
  list-style: none;
  margin: 14px 0 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 10px;
  max-height: 62vh;
  overflow-y: auto;
}

.record-item {
  display: grid;
  grid-template-columns: 1fr auto;
  gap: 10px;
  align-items: center;
  background: var(--panel-soft);
  border: 1px solid var(--line);
  border-left: 4px solid var(--accent);
  border-radius: 12px;
  padding: 12px 14px;
}

.record-item.is-income { border-left-color: var(--income); }
.record-item.is-expense { border-left-color: var(--expense); }

.record-main {
  min-width: 0;
}

.record-top {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px;
}

.record-category {
  font-weight: 600;
  font-size: 15px;
}

.tag {
  font-size: 12px;
  border-radius: 999px;
  padding: 1px 9px;
  border: 1px solid var(--line);
  color: var(--text-dim);
}

.tag-income {
  color: var(--income);
  border-color: rgba(53, 211, 154, 0.5);
  background: rgba(53, 211, 154, 0.12);
}

.tag-expense {
  color: var(--expense);
  border-color: rgba(255, 122, 134, 0.5);
  background: rgba(255, 122, 134, 0.12);
}

.record-date {
  font-size: 12px;
  color: var(--text-dim);
  font-variant-numeric: tabular-nums;
}

.record-note {
  margin: 4px 0 0;
  font-size: 13px;
  color: var(--text-dim);
  word-break: break-word;
}

.record-side {
  display: flex;
  align-items: center;
  gap: 12px;
}

.record-amount {
  font-size: 17px;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}

.record-amount.is-income { color: var(--income); }
.record-amount.is-expense { color: var(--expense); }

.empty-state {
  margin: 18px 0 4px;
  padding: 26px 16px;
  text-align: center;
  color: var(--text-dim);
  font-size: 14px;
  border: 1px dashed var(--line);
  border-radius: 12px;
  background: rgba(36, 57, 90, 0.4);
}

/* ---------- dialog ---------- */
.dialog-backdrop {
  position: fixed;
  inset: 0;
  background: rgba(6, 14, 26, 0.72);
  display: grid;
  place-items: center;
  padding: 20px;
  z-index: 50;
}

.dialog-backdrop[hidden] {
  display: none;
}

.dialog {
  width: min(420px, 100%);
  background: var(--panel);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  padding: 20px 22px;
  box-shadow: 0 24px 60px rgba(0, 0, 0, 0.5);
}

.dialog-title {
  margin: 0 0 8px;
  font-size: 17px;
}

.dialog-text {
  margin: 0 0 18px;
  font-size: 14px;
  color: var(--text-dim);
  word-break: break-word;
}

.dialog-actions {
  display: flex;
  justify-content: flex-end;
  gap: 10px;
}
